        detail=decision.message,
        headers={
            "Retry-After": str(decision.retry_after),
            "X-RateLimit-Limit": str(decision.limit),
            "X-RateLimit-Reset": str(int(time.time()) + decision.retry_after),   # unix time when it is allowed again
