import { ApiError, errorFromStatus } from './errors'

// POST /ask/stream: the answer arrives word by word as server-sent events.
//   event: token  data: {"text": "..."}        a piece of the answer
//   event: done   data: <AskResponse>           once, after the turn is saved (its `answer` is the one to trust)
//   event: error  data: {"status", "detail"}    something failed after tokens had started (nothing was saved)
//
// This is the one call that uses fetch: axios cannot read a response body as a stream in the browser, and the
// browser's EventSource cannot send a POST or an Authorization header.
// A problem BEFORE the first token is a normal HTTP error (401/404/429/503...) and is thrown as an ApiError, like
// every axios call. Cancel with `signal` (the Stop button): an AbortError is thrown and the backend saves nothing.
export async function askStream({ query, conversationId, onToken, signal }) {
  const token = await getAuthToken()
  let response
  try {
    response = await fetch(`${api.defaults.baseURL}/ask/stream`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: JSON.stringify({ query, conversation_id: conversationId ?? null }),
      signal,
    })
  } catch (error) {
    if (error.name === 'AbortError') throw error
    throw new ApiError('Cannot reach the server. Check that the backend is running.', { code: 'network' })
  }

  if (!response.ok) {
    let body = null
    try {
      body = await response.json()
    } catch {
      /* not JSON */
    }
    throw errorFromStatus(response.status, body?.detail, response.headers.get('retry-after'))
  }

  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let buffer = ''
  let done = null

class Decision:
    """The verdict for one check."""

    allowed: bool
    retry_after: int = 0     # seconds to wait before trying again (only when denied)
    limit: int = 0           # the limit that applied (for the X-RateLimit-Limit header)
    message: str = ""        # what the client is told (only when denied)


@lru_cache(maxsize=1)
def _client() -> redis.Redis:
    """One shared connection pool, created on first use (importing this module connects to nothing)."""
    return redis.Redis.from_url(
        settings.redis_url,
        socket_connect_timeout=REDIS_TIMEOUT_SECONDS,
        socket_timeout=REDIS_TIMEOUT_SECONDS,
        decode_responses=True,
    )


@lru_cache(maxsize=1)
def _scripts():
    """The Lua scripts, registered once. redis-py sends the cheap EVALSHA and loads the script if Redis lacks it."""
    client = _client()
    return client.register_script(TOKEN_BUCKET_LUA), client.register_script(DAILY_COUNTER_LUA)


def seconds_until_utc_midnight(now: datetime | None = None) -> int:
    now = now or datetime.now(timezone.utc)
    midnight = (now + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    return max(1, math.ceil((midnight - now).total_seconds()))


def take_token(key: str, capacity: int, period_seconds: int, what: str) -> Decision:
    """
    Token bucket: allow `capacity` requests per `period_seconds` (refilling steadily), per `key`.
    `what` names the thing being limited in the message ("questions", "uploads").
    """
    try:
        bucket, _ = _scripts()
        allowed, wait, *_ = bucket(keys=[key], args=[capacity, capacity / period_seconds])
    except (redis.RedisError, OSError):
        logger.warning("Rate limiter: Redis is unavailable, letting the request through", exc_info=True)
        return Decision(allowed=True)

    if int(allowed) == 1:
        return Decision(allowed=True, limit=capacity)

    seconds = max(1, math.ceil(float(wait)))
    return Decision(
        allowed=False,
        retry_after=seconds,
        limit=capacity,
        message=f"Too many {what}. Try again in {seconds} seconds.",
    )

