function detailText(detail) {
  if (typeof detail === 'string') return detail
  if (Array.isArray(detail) && typeof detail[0]?.msg === 'string') return detail[0].msg
  return null
}

// axios error -> ApiError
export function toApiError(error) {
  if (error instanceof ApiError) return error

  const response = error?.response
  if (!response) {
    // No answer at all: the backend is down, VITE_API_URL is wrong, or the browser blocked the call (CORS).
    return new ApiError('Cannot reach the server. Check that the backend is running.', { code: 'network' })
  }

  const { status, data, headers } = response
  return errorFromStatus(status, data?.detail, headers?.['retry-after'])
}

// An HTTP error status (+ the backend's `detail` and the Retry-After header) -> ApiError. Shared by axios calls and
// the streaming chat call (fetch).
export function errorFromStatus(status, rawDetail, retryAfterHeader) {
  const detail = detailText(rawDetail)

  if (status === 401) return new ApiError('Your session has expired. Please sign in again.', { status, code: 'auth' })
  if (status === 404) return new ApiError(detail || 'Not found.', { status, code: 'not_found' })
  if (status === 413) return new ApiError('That file is too large (20 MB maximum).', { status, code: 'too_large' })
  if (status === 422) return new ApiError(detail || 'Some of the information is not valid.', { status, code: 'validation' })
  if (status === 429) {
    return new ApiError(detail || 'Too many requests. Please slow down.', {
      status,
      code: 'rate_limited',
      retryAfter: parseRetryAfter(retryAfterHeader),
    })
  }
  if (status >= 500) return new ApiError(detail || 'The server had a problem. Please try again.', { status, code: 'server' })
  return new ApiError(detail || `The request failed (${status}).`, { status })
}

const POLL_MS = 2500 // how often a processing document is checked

// The files being added from the question box. Each item:
//   { key, name, size, status, progress, error, documentId, failureReason, duplicate }
// status: 'uploading' (bytes going up) -> the document's own status 'pending' | 'processing' | 'ready' | 'failed',
//         or 'rejected' (refused before upload) / 'error' (the upload itself failed).
// Files upload ONE AT A TIME (a queue), so a big batch does not burst the backend's hourly upload limit at once and
// every chip gets a clear result. While anything is pending/processing it is re-checked every 2.5 s. A finished file
// stays in the list (shown as a plain name chip).
// discard(key) = the chip's X: it DELETES the document from the library (or cancels an upload that is queued or still
// sending). reset() = a new chat: the list starts empty again (documents stay in the library).
// getConversationId(): async, returns the id of the conversation the files belong to (ChatLayout creates it on the
// first upload of a new chat). Every upload is attached to it.
// mode ('docs' | 'code', CODEBASE-FEATURE): the chat's mode decides which files are accepted before anything is uploaded.
export function useUploads(getConversationId, mode = 'docs') {
  const [items, setItems] = useState([])
  const queue = useRef(Promise.resolve())
  const controllers = useRef(new Map()) // key -> AbortController of the upload in flight
  const cancelled = useRef(new Set()) // keys the user removed before their upload finished
  const itemsRef = useRef(items)
  useEffect(() => {
    itemsRef.current = items
  }, [items])

  const patch = useCallback((key, changes) => {
    setItems((all) => all.map((item) => (item.key === key ? { ...item, ...changes } : item)))
  }, [])

  const remove = useCallback((key) => setItems((all) => all.filter((item) => item.key !== key)), [])

